-- ---------------- 4. 系统菜单平台引擎组（幂等补插：仅当 Code 不存在时插入） ----------------

INSERT INTO SysMenu (ParentId, Code, Name, Icon, Url, TargetType, IsAddToDesktop, SortNo, IsActive, PermissionCode) SELECT NULL, 'platform-engine', '平台引擎', '⚙️', NULL, 'Iframe', 1, 3, 1, 'platform' WHERE NOT EXISTS (SELECT 1 FROM SysMenu WHERE Code='platform-engine');INSERT INTO SysMenu (ParentId, Code, Name, Icon, Url, TargetType, IsAddToDesktop, SortNo, IsActive, PermissionCode) SELECT (SELECT Id FROM SysMenu WHERE Code='platform-engine'), 'tpl-mgmt', '页面模板', '📋', '/Platform/Mgmt/DynTemplateMgmt', 'FullScreen', 1, 1, 1, 'platform.tpl' WHERE NOT EXISTS (SELECT 1 FROM SysMenu WHERE Code='tpl-mgmt');INSERT INTO SysMenu (ParentId, Code, Name, Icon, Url, TargetType, IsAddToDesktop, SortNo, IsActive, PermissionCode) SELECT (SELECT Id FROM SysMenu WHERE Code='platform-engine'), 'webpage-mgmt', '页面实例', '📦', '/Platform/Mgmt/DynWebPageMgmt', 'FullScreen', 1, 2, 1, 'platform.page' WHERE NOT EXISTS (SELECT 1 FROM SysMenu WHERE Code='webpage-mgmt');INSERT INTO SysMenu (ParentId, Code, Name, Icon, Url, TargetType, IsAddToDesktop, SortNo, IsActive, PermissionCode) SELECT (SELECT Id FROM SysMenu WHERE Code='platform-engine'), 'setting-mgmt', '页面设置管理', '📄', '/Platform/Shell/Runtime?id=' || (SELECT Id FROM DynWebPage WHERE Code='page-setting-mgmt'), 'Iframe', 1, 3, 1, 'platform.setting' WHERE NOT EXISTS (SELECT 1 FROM SysMenu WHERE Code='setting-mgmt');INSERT INTO SysMenu (ParentId, Code, Name, Icon, Url, TargetType, IsAddToDesktop, SortNo, IsActive) SELECT (SELECT Id FROM SysMenu WHERE Code='platform-engine'), 'solution-page', '解决方案', '💡', '/Platform/Shell/Runtime?id=26', 'Iframe', 1, 4, 1 WHERE NOT EXISTS (SELECT 1 FROM SysMenu WHERE Code='solution-page');
